// BaseNode.js
// Core abstraction for all node types. 
// Each node just passes a config object — no boilerplate duplication.

import { Handle, Position } from 'reactflow';

/**
 * BaseNode renders any node given a config:
 * {
 *   title: string,
 *   icon: string (emoji or char),
 *   color: string (accent hex),
 *   inputs: [{ id, label, style? }],
 *   outputs: [{ id, label, style? }],
 *   children: ReactNode (custom content inside card),
 *   width: number,
 *   minHeight: number,
 * }
 */
export const BaseNode = ({ id, config, children }) => {
  const {
    title,
    icon,
    color = '#6366f1',
    inputs = [],
    outputs = [],
    width = 220,
    minHeight = 90,
  } = config;

  return (
    <div className="base-node" style={{ width, minHeight, '--node-accent': color }}>
      {/* Input handles */}
      {inputs.map((handle, i) => (
        <Handle
          key={handle.id}
          type="target"
          position={Position.Left}
          id={`${id}-${handle.id}`}
          style={{
            top: inputs.length === 1 ? '50%' : `${((i + 1) / (inputs.length + 1)) * 100}%`,
            ...handle.style,
          }}
          className="node-handle node-handle--input"
        >
          {handle.label && (
            <span className="handle-label handle-label--left">{handle.label}</span>
          )}
        </Handle>
      ))}

      {/* Header */}
      <div className="node-header" style={{ background: color }}>
        <span className="node-icon">{icon}</span>
        <span className="node-title">{title}</span>
      </div>

      {/* Body */}
      <div className="node-body">
        {children}
      </div>

      {/* Output handles */}
      {outputs.map((handle, i) => (
        <Handle
          key={handle.id}
          type="source"
          position={Position.Right}
          id={`${id}-${handle.id}`}
          style={{
            top: outputs.length === 1 ? '50%' : `${((i + 1) / (outputs.length + 1)) * 100}%`,
            ...handle.style,
          }}
          className="node-handle node-handle--output"
        >
          {handle.label && (
            <span className="handle-label handle-label--right">{handle.label}</span>
          )}
        </Handle>
      ))}
    </div>
  );
};
